// rb3-app link stubs, C++ half (lane A0, 2026-11-22). Native only.
//
// rb3-app links the real App boot. What it cannot link yet is stood in for
// here and in rb3_app_link_stubs.s (generated by tools/rb3_app_link_stubs_gen.py
// from the link's undefined list). The rules:
//   * No stub returns. Every function stub ends in rb3_app_stub_reached(),
//     which names its ring and the function, then aborts.
//   * Every definition carries `// ring: <tag>`, read by
//     tools/native_stub_census.py --rings. online-* / xbox-* are the
//     out-of-scope ring (Quazal, NetSession, matchmaking, RockCentral, Live,
//     store); a1-* / a2-* / a4-* / a6-* name the milestone that owes the real
//     body (docs: /home/free/tmp/claude-1000/rb3-scout/xenon/PLAN.md section 3).
//   * Stubs are STRONG: when a real TU joins rb3-app the link fails with a
//     duplicate, so a stub and its real body never meet silently.
//
// The data globals below need their C++ type (for the size), so they are not
// generated. They are NOT constructed objects: zero bytes where the real
// global is an object (TheNet, TheRockCentral, TheBandUI, ...), null where it
// is a pointer or a reference. Reading one is an A1 crash site, not a value.
#include <cstdio>
#include <cstdlib>
#include "meta_band/BandUI.h"
#include "meta/WiiProfileMgr.h"
#include "meta_band/WiiFriendsProvider.h"
#include "net/Net.h"
#include "net/WiiFriendMgr.h"
#include "net_band/RockCentral.h"
#include "obj/Msg.h"

extern "C" [[noreturn]] void rb3_app_stub_reached(const char *ring, const char *fn) {
    fprintf(stderr, "rb3-app: UNREACHED stub [ring %s] %s\n", ring, fn);
    fflush(stderr);
    abort();
}

extern "C" [[noreturn]] void rb3_app_vcall_unreached() {
    fprintf(stderr, "rb3-app: UNREACHED virtual call through a stub vtable "
                    "(rb3_app_link_stubs.s)\n");
    fflush(stderr);
    abort();
}

// ---- objects: zero bytes, never constructed ----------------------------------
alignas(Net) unsigned char gRb3AppTheNet[sizeof(Net)] __asm__("TheNet"); // ring: online-net
alignas(RockCentral) unsigned char gRb3AppTheRockCentral[sizeof(RockCentral)] __asm__("TheRockCentral"); // ring: online-rockcentral
alignas(BandUI) unsigned char gRb3AppTheBandUI[sizeof(BandUI)] __asm__("TheBandUI"); // ring: a1-absent-body
alignas(WiiFriendMgr) unsigned char gRb3AppTheWiiFriendMgr[sizeof(WiiFriendMgr)] __asm__("TheWiiFriendMgr"); // ring: a4-wii-residue
alignas(WiiProfileMgr) unsigned char gRb3AppTheWiiProfileMgr[sizeof(WiiProfileMgr)] __asm__("TheWiiProfileMgr"); // ring: a4-wii-residue
alignas(WiiFriendsProvider) unsigned char gRb3AppTheWiiFriendsProvider[sizeof(WiiFriendsProvider)] __asm__("TheWiiFriendsProvider"); // ring: a4-wii-residue
// Declared only inside MetaPanel.cpp / MovieSys.cpp: no header gives the size,
// so these reserve 4 KiB of zeroes (an over-estimate, measured nowhere).
alignas(16) unsigned char gRb3AppTheWiiInvitationsProvider[4096] __asm__("TheWiiInvitationsProvider"); // ring: a4-wii-residue
alignas(16) unsigned char gRb3AppBinkMovieSys[4096] __asm__("gBinkMovieSys"); // ring: a2-movie
